window.docContents[31].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/#chapter-05___section-5-24":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.24. Problems","id":"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/#chapter-05___section-5-24"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Section-5___2___-Algebraic-numbers-and-algebraic-integers/#Chapter5___Introduction_5___2___heading-1":{"contents":"We are now passing to deeper results in the representation theory of finite groups. These results require the theory of algebraic numbers, which we will now briefly review.\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.2. Algebraic numbers and algebraic integers\tSection 5.2: Algebraic numbers and algebraic integers","header":"5.2. Algebraic numbers and algebraic integers","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Section-5___2___-Algebraic-numbers-and-algebraic-integers/#Chapter5___Introduction_5___2___heading-1"},"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Equivalence-of-categories/#Chapter7___Definition7___4___1":{"contents":"Definition 7.4.1. A functor F : \\mathcal{C} \\to \\mathcal{D} is an equivalence of categories if there exists F' : \\mathcal{D} \\to \\mathcal{C} such that F \\circ F' and F' \\circ F are isomorphic to the identity functors.\n\nIn this situation, F' is said to be a quasi-inverse to F.\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.4. Equivalence of categories\tEquivalence of categories","header":"Equivalence of categories","id":"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Equivalence-of-categories/#Chapter7___Definition7___4___1"},"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/Projective-cover/#Chapter9___Definition9___2___2":{"contents":"Definition 9.2.2. The projective module P_i is called the projective cover of M_i.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.2. Projective covers\tProjective cover","header":"Projective cover","id":"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/Projective-cover/#Chapter9___Definition9___2___2"}});
